const names={junior:['Ananya Mishra','Aditya Sahoo','Snehashish Das','Priyanka Panda','Rohan Mohanty','Ishita Patra','Swayam Rout','Sakshi Behera','Aryan Nayak','Diya Pradhan','Sourav Jena','Riya Sahu'],cs:['Shreya Mohanty','Ayush Das','Debasish Panda','Sneha Rout','Ritwik Mishra','Ankita Sahoo','Harsh Patra','Pooja Nayak','Siddharth Jena','Anushka Behera'],core:['Siddhi Panda','Sambit Sahoo','Pratik Das','Swati Mishra','Aman Rout','Ipsita Patra','Raj Mohanty','Nisha Jena','Arnav Nayak','Tanya Behera']};
const scores=[[88,91,97],[93,87,92],[86,94,88],[89,83,91],[81,90,87],[85,84,86],[77,88,89],[84,79,85],[79,82,83],[75,85,81],[78,76,80],[73,77,79]];
const datasets=Object.fromEntries(Object.entries(names).map(([key,list])=>[key,list.map((name,i)=>({name,id:`${key==='junior'?'26':'24'}${key==='core'?'EC':'CS'}${String(101+i).padStart(3,'0')}`,scores:scores[i].map((v,j)=>v-(key==='core'?2:key==='cs'?1:0)),index:i}))]));let category='junior',period='all';const $=s=>document.querySelector(s);const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');const total=p=>period==='all'?p.scores.reduce((a,b)=>a+b,0):p.scores[Number(period)];
function render(){const key=category==='junior'?'junior':$('#track').value;const data=[...datasets[key]].sort((a,b)=>total(b)-total(a));data.forEach((p,i)=>p.rank=i&&total(p)===total(data[i-1])?data[i-1].rank:i+1);const max=period==='all'?300:100;$('#max').textContent=max;const order=[data[1],data[0],data[2]];$('#podium').innerHTML=order.map((p,i)=>`<article class="pod-entry ${['second','first','third'][i]}"><div class="pod-person"><div class="avatar ${i===0?'lavender':i===2?'blue':''}">${i===1?'<span class="crown">♛</span>':''}${initials(p.name)}</div><h3>${p.name}</h3><span class="pod-points">${total(p)}<small>PTS</small></span></div><div class="pod-block"><strong>${p.rank}</strong><span>${['THE CHALLENGER','THE PACESETTER','THE CONTENDER'][i]}</span></div></article>`).join('');const query=$('#search').value.trim().toLowerCase();const filtered=data.filter(p=>(p.name+' '+p.id).toLowerCase().includes(query));$('#count').textContent=`${filtered.length} of ${data.length} contenders · ${category==='junior'?'Junior':key==='cs'?'Senior / CS':'Senior / Core'} · ${period==='all'?'Cumulative':`Week ${Number(period)+1}`}`;$('#rows').innerHTML=filtered.length?filtered.map(p=>`<article class="rank-row ${p.rank===1?'leader':''}"><span class="rank-number">${p.rank}</span><span class="avatar ${p.index%3===1?'lavender':p.index%3===2?'blue':''}">${initials(p.name)}</span><div class="rank-info"><h3>${p.name}</h3><div class="rank-meta"><span>${p.id}</span><span>·</span><span class="mini-score">${period==='all'?p.scores.map((s,j)=>`W${j+1} ${s}`).join(' / '):`Week ${Number(period)+1} score`}</span></div></div><div class="rank-total"><strong>${total(p)}</strong><small>pts</small><div class="bar"><span style="width:${total(p)/max*100}%"></span></div></div></article>`).join(''):`<p class="empty">No contenders found. Try another name or student ID.</p>`;const weekly=[...datasets[key]].sort((a,b)=>b.scores[2]-a.scores[2])[0];$('#recognition').innerHTML=`<article class="highlight"><span class="highlight-icon">✧</span><div><small>WEEK 3 / TOP PERFORMER</small><h3>${weekly.name}</h3><p>${weekly.scores[2]} / 100 · Leading by example.</p></div></article><article class="highlight"><span class="highlight-icon">↗</span><div><small>THE BIGGEST CLIMBER</small><h3>Progress gets noticed.</h3><p>Weekly recognition for the biggest move up the ranks.</p></div></article><article class="highlight"><span class="highlight-icon">◎</span><div><small>THE PERFECT FIVE</small><h3>Show up. All five weeks.</h3><p>Consistency deserves its own spotlight.</p></div></article>`;}
document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#track').hidden=category==='junior';render()}));$('#week').addEventListener('change',e=>{period=e.target.value;render()});$('#track').addEventListener('change',render);$('#search').addEventListener('input',render);render();
function theme(value){document.documentElement.dataset.theme=value;document.querySelectorAll('button[data-theme]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.theme===value));document.querySelector('meta[name="theme-color"]').content=value==='dark'?'#10141e':'#f5f4ef';try{localStorage.setItem('ax-theme',value)}catch(e){}}
document.querySelectorAll('button[data-theme]').forEach(b=>b.addEventListener('click',()=>theme(b.dataset.theme)));theme(document.documentElement.dataset.theme||'dark');
const labels={leaderboard:'Leaderboard',team:'Our Team',schedule:'Schedule of Examination',about:'About AchieveX'};function route(){const page=location.hash.slice(1) in labels?location.hash.slice(1):'leaderboard';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==page);document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#page-label').textContent=labels[page];document.title=`${labels[page]} — AchieveX`;window.scrollTo({top:0,behavior:"instant"})}window.addEventListener('hashchange',route);route();
$('#schedule-list').innerHTML=Array.from({length:5},(_,i)=>`<article class="exam"><span class="exam-number">0${i+1}</span><div><h3>Round ${i+1}</h3><p>Junior · Senior CS · Senior Core<br>100 points per assessment</p></div><div class="exam-meta"><b>Date to be announced</b><span>Time & venue awaited</span></div></article>`).join('');const subjects={junior:['Aptitude','BEE / Basic Electronics','English','C Programming & Debugging','Basic Mathematics'],cs:['Aptitude','C Programming','SQL & OS','DSA & Python Basics','OOPs in Java'],core:['Aptitude','C & Python','Electronics Basics','Signals & Systems','Circuit Theory']};function showSubjects(){$('#subject-list').innerHTML=subjects[$('#subjects').value].map(s=>`<span>${s}</span>`).join('')}$('#subjects').addEventListener('change',showSubjects);showSubjects();
